// Вэб chat-аас ирсэн { sessionId, message, name } задлах → AI Agent-д agentInput.
const body = $input.first().json.body || {};
const sessionId = String(body.sessionId || 'web_anon').slice(0, 64);
const userText = String(body.message || '').trim();
const name = (body.name || '').trim();
if (!userText) {
  return [{ json: { psid: sessionId, userText: '', agentInput: '', empty: true } }];
}
const NL = String.fromCharCode(10);
const nameLine = name ? ('Хэрэглэгчийн нэр: ' + name) : '';

// ⚠️ Холбоо барих/бидний тухай БОДИТ DB өгөгдлийг ЗӨВХӨН тийм асуулт илэрсэн үед
// агентад оруулна. AI зохиохгүй — энэ өгөгдлөөр л хариулна. FB chatbot-той ИЖИЛ.
const lower = (userText || '').toLowerCase();
const contactTriggers = [
  'утас', 'дугаар', 'хаяг', 'холбоо', 'холбогд', 'имэйл', 'мэйл', 'и-мэйл',
  'хаана байр', 'байршил', 'ажлын цаг', 'цагаар', 'социал', 'фэйсбүүк',
  'facebook', 'instagram', 'инстаграм', 'бидний тухай', 'танай тухай', 'хэн бэ',
  'хаягтай', 'утастай', 'phone', 'contact', 'address', 'хаа байдаг', 'хаана байдаг',
];
const needsContact = contactTriggers.some((t) => lower.includes(t));

let contextLine = '';
if (needsContact) {
  try {
    const resp = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://api.digitalger.mn/api/contact/chatbot-context',
      json: true,
      timeout: 4000,
    });
    const cb = (resp && resp.contextBlock) ? String(resp.contextBlock) : '';
    if (cb) {
      contextLine = NL + '=== ХОЛБОО БАРИХ / БИДНИЙ ТУХАЙ (БОДИТ ӨГӨГДӨЛ — холбоо барих, утас, хаяг, бидний тухай асуувал ЗӨВХӨН ЭНДЭЭС бодит мэдээллээр хариул, ЮУ Ч БҮҮ ЗОХИО) ===' + NL + cb;
    }
  } catch (e) {
    contextLine = '';
  }
}

const agentInput = [nameLine, contextLine, '=== ХЭРЭГЛЭГЧИЙН МЕССЕЖ ===', userText].filter(Boolean).join(NL);
return [{ json: { psid: sessionId, userText, agentInput } }];

// Extract Keyword — AI Agent-ийн хариунаас [SEARCH:keyword] салгана.
// keyword байвал → дараагийн HTTP node backend-ийг ЦЭВЭР keyword-оор дуудна.
// [SEARCH:...] тэмдгийг хэрэглэгчид харагдах текстээс арилгана.
const prep = $('Prep').first().json;
const psid = prep.psid;
const platform = 'web';
let raw = ($input.first().json.output || '').trim();
// [SEARCH:xxx] эсвэл [SEARCH: xxx] хайх (кирилл/латин/зай хүлээнэ)
let keyword = '';
const m = raw.match(/\[SEARCH:\s*([^\]]*)\]/i);
if (m) {
  keyword = (m[1] || '').trim();
}
// Тэмдгийг текстээс бүрэн арилгана (хэд ч байж болно)
let replyText = raw.replace(/\[SEARCH:[^\]]*\]/ig, '').trim();
// Markdown цэвэрлэх: [текст](url) → "текст url", ** __ устгах
function stripMd(s){ s=String(s||''); var r='',i=0; while(i<s.length){ if(s[i]==='['){ var c=s.indexOf('](',i); if(c!==-1){ var e=s.indexOf(')',c+2); if(e!==-1){ var t=s.slice(i+1,c).trim(); var u=s.slice(c+2,e).trim(); r+=(t===u||!t)?u:(t+' '+u); i=e+1; continue; } } } r+=s[i]; i++; } r=r.split('**').join('').split('__').join(''); var parts=r.split(' '); var out=[]; for(var k=0;k<parts.length;k++){ if(k>0 && parts[k]!=='' && parts[k]===parts[k-1]){ continue; } out.push(parts[k]); } r=out.join(' '); return r.trim(); }
replyText = stripMd(replyText);

// ⚠️ FAQ ХАМГААЛАЛТ: AI андуурч ерөнхий FAQ/үйл үгийг [SEARCH:]-д тавьсан бол
// хайлт ХИЙХГҮЙ (AI-гийн текст хариуг шууд илгээнэ). Энэ нь "татаж авах яаж"
// гэх ерөнхий асуулт буруугаар бүтээгдэхүүн хайж "олдсонгүй" гэхээс сэргийлнэ.
const kwLc = keyword.toLowerCase().replace(/\s+/g, ' ').trim();
const FAQ_STOP = ['татаж авах','татах','худалдан авах','худалдаж авах','авах заавар','төлбөр','тулбур','qpay','купон','буцаалт','буцаан','формат','эрх','хэрхэн','яаж','хэрэглэх','ашиглах','нэвтрэх','бүртгэл','бүртгүүлэх','нууц үг','имэйл','видео хичээл үзэх','хичээл үзэх','үзэх заавар','тусламж','холбоо барих','админ','хэдэн төхөөрөмж','интернэт','офлайн','хэр удаан','хэдэн удаа','хямдрал','үнэ төлбөр'];
let isFaqLike = false;
for (let i = 0; i < FAQ_STOP.length; i++) { if (kwLc === FAQ_STOP[i]) { isFaqLike = true; break; } }
if (isFaqLike) {
  keyword = '';
}

const doSearch = keyword.length >= 2;
if (!replyText) replyText = doSearch ? 'Танд тохирох бүтээгдэхүүн хайж байна...' : 'Уучлаарай, дахин бичнэ үү.';
return [{ json: { psid, keyword, doSearch, replyText } }];

// Build JSON — Extract Keyword-ийн replyText + Search-ийн products-ийг
// вэб widget-д зориулсан JSON болгон угсарна: { reply, products[] }.
const ex = $('Extract Keyword').first().json;
const replyText = (ex.replyText || '').trim() || 'Уучлаарай, дахин бичнэ үү.';
let search = {};
try { search = $('Search by Keyword').first().json || {}; } catch (e) { search = {}; }
const triedSearch = ex.doSearch === true;
const raw = (triedSearch && Array.isArray(search.products)) ? search.products : [];

// Widget-д зориулсан цэвэр бүтээгдэхүүн объект (эхний 6)
const products = raw.slice(0, 6).map(function (p) {
  return {
    id: p.id || null,
    title: p.title || '',
    price: (p.price != null) ? Number(p.price) : null,
    salePrice: (p.salePrice != null) ? Number(p.salePrice) : null,
    imageUrl: p.imageUrl || null,
    url: p.url || null,
  };
});

return [{ json: { reply: replyText, products } }];
